<?php $entry = $data['entry']; ?>
<div class="page-heading"><div><p class="eyebrow">DATEIABLAGE</p><h1><?= $e($entry['name']) ?></h1><p class="lead">Aktueller Stand: Revision <?= $e($entry['revision']) ?>. Frühere Inhalte bleiben erhalten und zählen zur Quote.</p></div><a href="<?= $e('/files/detail?' . http_build_query(['space' => $data['space_id'], 'entry' => $entry['id']])) ?>">Zur Datei</a></div>
<section class="panel"><div class="panel-heading"><h2>Gesicherte frühere Versionen</h2></div><div class="group-list">
<?php foreach ($data['versions'] as $version): ?><article class="group-row"><div><h3>Revision <?= $e($version['revision']) ?></h3><p class="subtle"><?= $e(number_format((int) $version['size_bytes'], 0, ',', '.')) ?> Bytes · gesichert am <?= $e(gmdate('Y-m-d H:i', (int) $version['created_at'])) ?> UTC</p><a href="<?= $e('/files/version/download?' . http_build_query(['space' => $data['space_id'], 'entry' => $entry['id'], 'version' => $version['id']])) ?>">Herunterladen</a></div>
<?php if ($data['can_update']): ?><form method="post" action="/files/version/restore"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($entry['id']) ?>"><input type="hidden" name="parent" value="<?= $e($entry['parent_id']) ?>"><input type="hidden" name="version" value="<?= $e($version['id']) ?>"><input type="hidden" name="revision" value="<?= $e($entry['revision']) ?>"><button class="button button-outline" type="submit">Als neuen Stand wiederherstellen</button></form><?php endif ?></article><?php endforeach ?>
<?php if ($data['versions'] === []): ?><p class="empty">Für diese Datei gibt es noch keine früheren Versionen.</p><?php endif ?></div>
<?php if ($data['next'] !== null): ?><a href="<?= $e('/files/versions?' . http_build_query(['space' => $data['space_id'], 'entry' => $entry['id'], 'after' => $data['next']])) ?>">Weitere Versionen</a><?php endif ?></section>
